function [phi] = phi_quad(a_sat, gm_body, r_body, e_body, mu)
%PHI_QUAD  thirdbody.secular.phiQuad(a_sat, GM_body, r_body, e_body, mu): the secular quadrupole frequency [rad/s] of a
%   perturber of GM gm_body on an orbit of radius r_body and eccentricity e_body, the satellite's semi-major axis a_sat.
%   a_sat: real[1] (passed a plain number)
%   gm_body: real[1] (passed a plain number)
%   r_body: real[1] (passed a plain number)
%   e_body: real[1] (passed a plain number)
%   mu: real[1] (passed a plain number)
%   returns phi: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    phi = 0;
    n = sqrt((mu / (a_sat)^(3)));
    phi = (((0.75 * (gm_body / (r_body)^(3))) / n) / ((1 - (e_body * e_body)))^(1.5));
end
